# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EV EŞYALARI VE ODALARA GÖRE DAĞILIMI (أَثَاثُ الْبَيْتِ)</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">غُرْفَةُ الْجُلُوسِ (Oturma Odası)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="12" fill="#1e3a8a">• أَرِيكَةٌ (Kanepe / Koltuk)</text>\n  <text x="125" y="124" text-anchor="middle" font-size="12" fill="#1e3a8a">• تِلْفَازٌ (Televizyon)</text>\n  <text x="125" y="150" text-anchor="middle" font-size="12" fill="#1e3a8a">• سَجَّادَةٌ (Halı)</text>\n  <text x="125" y="176" text-anchor="middle" font-size="12" fill="#1e3a8a">• طَاوِلَةٌ (Masa / Sehpa)</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">فِي غُرْفَةِ الْجُلُوسِ أَرِيكَةٌ</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">غُرْفَةُ النَّوْمِ (Yatak Odası)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" fill="#14532d">• سَرِيرٌ (Yatak)</text>\n  <text x="350" y="124" text-anchor="middle" font-size="12" fill="#14532d">• خِزَانَةٌ (Dolap / Gardırop)</text>\n  <text x="350" y="150" text-anchor="middle" font-size="12" fill="#14532d">• وِسَادَةٌ (Yastık)</text>\n  <text x="350" y="176" text-anchor="middle" font-size="12" fill="#14532d">• مِرْآةٌ (Ayna) / مِصْبَاحٌ (Lamba)</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">فِي غُرْفَةِ النَّوْمِ سَرِيرٌ وَخِزَانَةٌ</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">اَلْمَطْبَخُ وَغُرْفَةُ الدِّرَاسَةِ</text>\n  <text x="575" y="98" text-anchor="middle" font-size="12" fill="#713f12">• ثَلَّاجَةٌ (Buzdolabı)</text>\n  <text x="575" y="124" text-anchor="middle" font-size="12" fill="#713f12">• فُرْنٌ (Fırın)</text>\n  <text x="575" y="150" text-anchor="middle" font-size="12" fill="#713f12">• مَكْتَبٌ (Çalışma Masası)</text>\n  <text x="575" y="176" text-anchor="middle" font-size="12" fill="#713f12">• كُرْسِيٌّ (Sandalye) / حَاسُوبٌ</text>\n  <text x="575" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">فِي الْمَطْبَخِ ثَلَّاجَةٌ وَفُرْنٌ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EVDE GÜNLÜK ETKİNLİKLER VE MUZÂRİ FİİLLER (الْأَفْعَالُ الْمُضَارِعَةُ)</text>\n  <rect x="20" y="48" width="320" height="90" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. يَجْلِسُ / تَجْلِسُ (Oturuyor)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" fill="#1e3a8a">يَجْلِسُ أَحْمَدُ عَلَى الْأَرِيكَةِ فِي غُرْفَةِ الْجُلُوسِ.</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#475569">(Ahmet oturma odasında kanepenin üzerinde oturuyor.)</text>\n\n  <rect x="360" y="48" width="320" height="90" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. يَطْبُخُ / تَطْبُخُ (Yemek Pişiriyor)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" fill="#9d174d">تَطْبُخُ الْأُمُّ الطَّعَامَ فِي الْمَطْبَخِ.</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#475569">(Anne mutfakta yemek pişiriyor.)</text>\n\n  <rect x="20" y="150" width="320" height="90" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. يَنَامُ / تَنَامُ (Uyuyor)</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" fill="#14532d">يَنَامُ الطِّفْلُ عَلَى السَّرِيرِ فِي غُرْفَةِ النَّوْمِ.</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" fill="#475569">(Çocuk yatak odasında yatağın üzerinde uyuyor.)</text>\n\n  <rect x="360" y="150" width="320" height="90" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">4. يَقْرَأُ / تَقْرَأُ (Okuyor)</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" fill="#581c87">تَقْرَأُ زَيْنَبُ الْكِتَابَ فِي غُرْفَةِ الدِّرَاسَةِ.</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" fill="#475569">(Zeynep çalışma odasında kitap okuyor.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SORU VE DİYALOG KALIPLARI (مَاذَا يَفْعَلُ؟ / أَيْنَ تُوجَدُ؟)</text>\n  <rect x="25" y="48" width="650" height="92" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Etkinlik Sorma Kalıbı: مَاذَا يَفْعَلُ ...؟ / مَاذَا تَفْعَلُ ...؟ (Ne yapıyor?)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• مَاذَا يَفْعَلُ الْأَبُ؟ ➔ هُوَ يُشَاهِدُ التِّلْفَازَ فِي غُرْفَةِ الْجُلُوسِ. (Baba TV izliyor.)</text>\n  <text x="350" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• مَاذَا تَفْعَلُ الْأُخْتُ؟ ➔ هِيَ تَكْتُبُ الْوَاجِبَ عَلَى الْمَكْتَبِ. (Kız kardeş ödev yazıyor.)</text>\n\n  <rect x="25" y="152" width="650" height="90" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. Konum ve Eşya Sorma Kalıbı: مَاذَا يُوجَدُ فِي ...؟ / أَيْنَ ...؟</text>\n  <text x="350" y="202" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">• مَاذَا يُوجَدُ فِي غُرْفَةِ النَّوْمِ؟ ➔ يُوجَدُ فِيهَا سَرِيرٌ وَخِزَانَةٌ مَلَابِسَ.</text>\n  <text x="350" y="226" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">• أَيْنَ الثَّلَّاجَةُ؟ ➔ الثَّلَّاجَةُ فِي الْمَطْبَخِ بَيْنَ الْفُرْنِ وَالنَّافِذَةِ.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
